    for p_el in root.findall('.//a:p', NS):
        parts = []
        for child in p_el.iter():
            if child.tag == '{%s}t' % NS['a'] and child.text:
                parts.append(child.text)
            elif child.tag == '{%s}br' % NS['a']:
                parts.append('\\n')
        text = clean_text(''.join(parts))
        if text:
            for part in text.split('\\n'):
                part = clean_text(part)
                if part and part.lower() not in PLACEHOLDERS:
                    paragraphs.append(part)
    return paragraphs

def rels_for(z, rels_path):
    if rels_path not in z.namelist():
        return {}
    root = ET.fromstring(z.read(rels_path))
    return {rel.attrib.get('Id'): rel.attrib for rel in root.findall(f'{REL_NS}Relationship')}

def resolve_target(base_file, target):
    base_dir = posixpath.dirname(base_file)
    return posixpath.normpath(posixpath.join(base_dir, target))

def slide_order(z):
    pres = ET.fromstring(z.read('ppt/presentation.xml'))
    pres_rels = rels_for(z, 'ppt/_rels/presentation.xml.rels')
    ordered = []
    for slide_id in pres.findall('.//p:sldId', NS):
        rid = slide_id.attrib.get('{%s}id' % NS['r'])
        rel = pres_rels.get(rid)
        if rel and rel.get('Target'):
            ordered.append(resolve_target('ppt/presentation.xml', rel['Target']))
    return ordered

def notes_path_for_slide(z, slide_path):
    rels_path = posixpath.join(posixpath.dirname(slide_path), '_rels', posixpath.basename(slide_path) + '.rels')
    for rel in rels_for(z, rels_path).values():
        if rel.get('Type', '').endswith('/notesSlide') and rel.get('Target'):
            return resolve_target(slide_path, rel['Target'])
    return None

def p(text='', style=None):
    text = html.escape(text, quote=False)
    ppr = f'<w:pPr><w:pStyle w:val=\"{style}\"/></w:pPr>' if style else ''
    return f'<w:p>{ppr}<w:r><w:t xml:space=\"preserve\">{text}</w:t></w:r></w:p>'

